// The brand's vector sources (design/brand/, generated by tools/brand):
// only token colours, text as outlines, nothing the brief rules out.
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

const _brand = '../design/brand';

/// The colours the brand may use, read from the tokens file itself, so a
/// token change and an SVG that did not follow it disagree here.
Set<String> _allowed() {
  final dart = File('lib/design/tokens.dart').readAsStringSync();
  String hex(String name) {
    final match = RegExp('static const $name = Color\\(0xFF([0-9A-Fa-f]{6})\\)').firstMatch(dart);
    expect(match, isNotNull, reason: 'token $name');
    return '#${match!.group(1)!.toUpperCase()}';
  }

  return {for (final name in ['i950', 'i050', 'meter500', 'meter700', 'paper']) hex(name)};
}

List<File> _svgs() => Directory(_brand).listSync().whereType<File>().where((f) => f.path.endsWith('.svg')).toList();

void main() {
  test('every source the brief lists is there', () {
    for (final name in [
      'logo-primary-on-dark',
      'logo-primary-on-light',
      'logo-mono-ink',
      'logo-mono-white',
      'icon-client',
      'icon-pro',
      'icon-foreground-client',
      'icon-foreground-pro',
      'icon-background-client',
      'icon-background-pro',
      'icon-monochrome',
    ]) {
      expect(File('$_brand/$name.svg').existsSync(), isTrue, reason: name);
    }
    expect(File('$_brand/exports/logo-primary-on-light@2x.png').existsSync(), isTrue);
    expect(File('$_brand/README.md').existsSync(), isTrue);
  });

  test('fills use only token colours', () {
    final allowed = _allowed();
    for (final file in _svgs()) {
      final used = RegExp(r'#[0-9A-Fa-f]{3,8}\b').allMatches(file.readAsStringSync()).map((m) => m.group(0)!.toUpperCase()).toSet();
      expect(used.difference(allowed), isEmpty, reason: '${file.path} uses ${used.difference(allowed)}; allowed: $allowed');
      expect(used, isNotEmpty, reason: file.path);
    }
  });

  test('one accent: a logo or icon never mixes the two Meters', () {
    final allowed = _allowed().toList();
    final meter500 = allowed[2];
    final meter700 = allowed[3];
    for (final file in _svgs()) {
      final svg = file.readAsStringSync().toUpperCase();
      expect(svg.contains(meter500) && svg.contains(meter700), isFalse, reason: file.path);
    }
  });

  test('text is outlines: no live font, no text element, no image', () {
    for (final file in _svgs()) {
      final svg = file.readAsStringSync();
      for (final banned in ['<text', '<tspan', 'font-family', '<image', '@font-face']) {
        expect(svg.contains(banned), isFalse, reason: '${file.path} has $banned');
      }
    }
  });

  test('no gradients, shadows, filters or transparency effects', () {
    for (final file in _svgs()) {
      final svg = file.readAsStringSync();
      for (final banned in ['Gradient', '<filter', 'opacity', '<mask', '<pattern']) {
        expect(svg.contains(banned), isFalse, reason: '${file.path} has $banned');
      }
    }
  });

  test('icon masters are 1024 squares on their grounds: client dark, pro paper', () {
    final allowed = _allowed().toList();
    for (final (name, ground) in [('icon-client', allowed[0]), ('icon-pro', allowed[4])]) {
      final svg = File('$_brand/$name.svg').readAsStringSync();
      expect(svg, contains('viewBox="0 0 1024 1024"'), reason: name);
      expect(RegExp(r'<rect width="1024" height="1024" fill="(#[0-9A-F]{6})"/>').firstMatch(svg)?.group(1), ground, reason: name);
    }
  });
}
